import math

objects = [
    {"shape": "square", "color": "blue"},
    {"shape": "circle", "color": "blue"},
    {"shape": "square", "color": "green"}
]

utterances = ["blue", "green", "square", "circle"]
alpha = 1.0

def meaning(utt, obj):
    if utt in ("blue", "green"):
        return utt == obj["color"]
    elif utt in ("circle", "square"):
        return utt == obj["shape"]
    return True

# Literal listener: p(obj|utt) proportional to meaning(utt,obj) * uniform prior
def literal_listener(utt):
    scores = []
    for obj in objects:
        scores.append(1.0 if meaning(utt, obj) else 0.0)
    total = sum(scores)
    return [s / total for s in scores]

# Speaker: p(utt|obj) proportional to exp(alpha * log L0(obj|utt))
def speaker(obj):
    obj_idx = objects.index(obj)
    scores = []
    for utt in utterances:
        ll = literal_listener(utt)
        p_obj = ll[obj_idx]
        if p_obj > 0:
            scores.append(math.exp(alpha * math.log(p_obj)))
        else:
            scores.append(0.0)
    total = sum(scores)
    return [s / total for s in scores]

# Pragmatic listener L1: p(obj|utt) proportional to speaker(obj, utt) * prior
def pragmatic_listener(utt):
    utt_idx = utterances.index(utt)
    scores = []
    for obj in objects:
        sp = speaker(obj)
        scores.append(sp[utt_idx] * (1.0 / len(objects)))
    total = sum(scores)
    return [s / total for s in scores]

# Speaker2: p(utt|obj) proportional to exp(alpha * log L1(obj|utt))
def speaker2(obj):
    obj_idx = objects.index(obj)
    scores = []
    for utt in utterances:
        pl = pragmatic_listener(utt)
        p_obj = pl[obj_idx]
        if p_obj > 0:
            scores.append(math.exp(alpha * math.log(p_obj)))
        else:
            scores.append(0.0)
    total = sum(scores)
    return [s / total for s in scores]

# Listener3 L2: p(obj|utt) proportional to speaker2(obj, utt) * prior
def listener3(utt):
    utt_idx = utterances.index(utt)
    scores = []
    for obj in objects:
        sp2 = speaker2(obj)
        scores.append(sp2[utt_idx] * (1.0 / len(objects)))
    total = sum(scores)
    return [s / total for s in scores]

# Compute L1 and L2 for utterance 'blue'
l1_probs = pragmatic_listener("blue")
l2_probs = listener3("blue")

# Build support sorted canonically (JSON serialization order: color then shape alphabetically)
import json

def obj_key(obj):
    return json.dumps(obj, sort_keys=True)

# Filter to non-zero probability objects and sort
l1_pairs = [(obj, p) for obj, p in zip(objects, l1_probs) if p > 0]
l1_pairs_sorted = sorted(l1_pairs, key=lambda x: obj_key(x[0]))

l2_pairs = [(obj, p) for obj, p in zip(objects, l2_probs) if p > 0]
l2_pairs_sorted = sorted(l2_pairs, key=lambda x: obj_key(x[0]))

ANSWER = {
    "L1": {
        "__kind": "distribution",
        "probs": [p for _, p in l1_pairs_sorted],
        "support": [o for o, _ in l1_pairs_sorted]
    },
    "L2": {
        "__kind": "distribution",
        "probs": [p for _, p in l2_pairs_sorted],
        "support": [o for o, _ in l2_pairs_sorted]
    }
}

