p_cancer = 0.00001
p_cold = 0.2
p_dbc_given_cancer = 0.9
p_dbcold_given_cold = 0.00006
p_other = 0.000000001

# Enumerate: cancer, cold, death_by_cancer, death_by_cold, other_death
# Each is bool

def compute_posterior(condition_fn):
    total = [0.0, 0.0]  # index 0: cancer=False, index 1: cancer=True
    for cancer in [False, True]:
        for cold in [False, True]:
            for dbc in [False, True]:
                for dbcold in [False, True]:
                    for od in [False, True]:
                        # death_by_cancer only possible if cancer
                        if dbc and not cancer:
                            continue
                        # death_by_cold only possible if cold
                        if dbcold and not cold:
                            continue

                        death = dbc or dbcold or od

                        # compute joint probability
                        p = 1.0
                        p *= p_cancer if cancer else (1 - p_cancer)
                        p *= p_cold if cold else (1 - p_cold)
                        if cancer:
                            p *= p_dbc_given_cancer if dbc else (1 - p_dbc_given_cancer)
                        else:
                            p *= 0.0 if dbc else 1.0
                        if cold:
                            p *= p_dbcold_given_cold if dbcold else (1 - p_dbcold_given_cold)
                        else:
                            p *= 0.0 if dbcold else 1.0
                        p *= p_other if od else (1 - p_other)

                        if condition_fn(cancer, cold, death):
                            total[1 if cancer else 0] += p

    s = total[0] + total[1]
    return {"__kind": "distribution", "probs": [total[0]/s, total[1]/s], "support": [False, True]}

