p_cancer = 0.00001
p_cold = 0.2
p_death_given_cancer = 0.9
p_death_given_cold = 0.00006
p_other_death = 0.000000001

# Enumerate over (cancer, cold, death_by_cancer, death_by_cold, other_death)
# Each is boolean (False/True)

def compute_marginal(condition_fn):
    prob_cold_false = 0.0
    prob_cold_true = 0.0
    for cancer in [False, True]:
        p_c = p_cancer if cancer else (1 - p_cancer)
        for cold in [False, True]:
            p_co = p_cold if cold else (1 - p_cold)
            for dbc in [False, True]:
                if cancer:
                    p_dbc = p_death_given_cancer if dbc else (1 - p_death_given_cancer)
                else:
                    p_dbc = 0.0 if dbc else 1.0
                for dbco in [False, True]:
                    if cold:
                        p_dbco = p_death_given_cold if dbco else (1 - p_death_given_cold)
                    else:
                        p_dbco = 0.0 if dbco else 1.0
                    for od in [False, True]:
                        p_od = p_other_death if od else (1 - p_other_death)
                        death = dbc or dbco or od
                        joint = p_c * p_co * p_dbc * p_dbco * p_od
                        if condition_fn(cancer, cold, death):
                            if cold:
                                prob_cold_true += joint
                            else:
                                prob_cold_false += joint
    total = prob_cold_false + prob_cold_true
    if total == 0:
        return {"__kind": "distribution", "probs": [0.5, 0.5], "support": [False, True]}
    return {
        "__kind": "distribution",
        "probs": [prob_cold_false / total, prob_cold_true / total],
        "support": [False, True]
    }

