import math

maxNumber = 20

def filter_in_range(lst):
    return list(dict.fromkeys([v for v in lst if 0 <= v <= maxNumber]))

def gen_evens():
    return [v for v in range(1, maxNumber) if v % 2 == 0]

def gen_odds():
    return [v for v in range(1, maxNumber) if (v + 1) % 2 == 0]

def gen_multiples(base):
    multiples = [base * v for v in range(maxNumber)]
    return filter_in_range(multiples)

def gen_powers(base):
    powers = [int(base ** v) for v in range(maxNumber)]
    return filter_in_range(powers)

def gen_set_from_interval(a, b):
    return list(range(a, b + 1))

def make_rule_hypothesis_space():
    multiple_rules = ['multiples_of_' + str(b) for b in range(1, 12)]
    power_rules = ['powers_of_' + str(b) for b in range(1, 12)]
    return multiple_rules + power_rules + ['evens', 'odds']

def make_interval_hypothesis_space(start, end):
    intervals = []
    for a in range(start, end + 1):
        for b in range(a + 1, end + 1):
            intervals.append('interval_' + str(a) + '_' + str(b))
    return intervals

def get_set_from_hypothesis(rule):
    parts = rule.split('_')
    if parts[0] == 'multiples':
        return gen_multiples(int(parts[2]))
    elif parts[0] == 'powers':
        return gen_powers(int(parts[2]))
    elif parts[0] == 'evens':
        return gen_evens()
    elif parts[0] == 'odds':
        return gen_odds()
    elif parts[0] == 'interval':
        return gen_set_from_interval(int(parts[1]), int(parts[2]))
    else:
        raise ValueError('unknown rule: ' + rule)

def learn_concept(examples, test_query):
    rules = make_rule_hypothesis_space()
    intervals = make_interval_hypothesis_space(1, maxNumber)
    n_rules = len(rules)
    n_intervals = len(intervals)

    # Prior: 50% rules, 50% intervals
    prior_rule = 0.5 / n_rules
    prior_interval = 0.5 / n_intervals

    results = {}

    def process_hyp(hyp, prior_weight):
        s = get_set_from_hypothesis(hyp)
        if len(s) == 0:
            return
        # Check all examples are in set
        for ex in examples:
            if ex not in s:
                return
        # Log likelihood
        log_lik = len(examples) * (-math.log(len(s)))
        log_w = math.log(prior_weight) + log_lik
        response = test_query in s
        key_dict = {'hypothesis': hyp, 'testQueryResponse': response}
        key = (hyp, response)
        if key in results:
            results[key] = (key_dict, results[key][1] + math.exp(log_w))
        else:
            results[key] = (key_dict, math.exp(log_w))

    for hyp in rules:
        process_hyp(hyp, prior_rule)
    for hyp in intervals:
        process_hyp(hyp, prior_interval)

    total = sum(v[1] for v in results.values())
    support = []
    probs = []
    for key_dict, w in results.values():
        support.append(key_dict)
        probs.append(w / total)

    return {'__kind': 'distribution', 'probs': probs, 'support': support}

ANSWER = learn_concept([3, 10], 12)

import math

maxNumber = 20

def filter_by_in_range(lst):
    seen = set()
    result = []
    for v in lst:
        if 0 <= v <= maxNumber and v not in seen:
            seen.add(v)
            result.append(v)
    return result

def gen_evens():
    return [v for v in range(1, maxNumber) if v % 2 == 0]

def gen_odds():
    return [v for v in range(1, maxNumber) if (v + 1) % 2 == 0]

def gen_multiples(base):
    multiples = [base * v for v in range(maxNumber)]
    return filter_by_in_range(multiples)

def gen_powers(base):
    powers = [int(base ** v) for v in range(maxNumber)]
    return filter_by_in_range(powers)

def gen_set_from_interval(a, b):
    return list(range(a, b + 1))

def make_rule_hypothesis_space():
    multiple_rules = ['multiples_of_' + str(b) for b in range(1, 12)]
    power_rules = ['powers_of_' + str(b) for b in range(1, 12)]
    return multiple_rules + power_rules + ['evens', 'odds']

def make_interval_hypothesis_space(start, end):
    intervals = []
    for s in range(start, end + 1):
        for e in range(s + 1, end + 1):
            intervals.append('interval_' + str(s) + '_' + str(e))
    return intervals

def get_set_from_hypothesis(rule):
    parts = rule.split('_')
    if parts[0] == 'multiples':
        return gen_multiples(int(parts[2]))
    elif parts[0] == 'powers':
        return gen_powers(int(parts[2]))
    elif parts[0] == 'evens':
        return gen_evens()
    elif parts[0] == 'odds':
        return gen_odds()
    elif parts[0] == 'interval':
        return gen_set_from_interval(int(parts[1]), int(parts[2]))
    else:
        raise ValueError('unknown rule: ' + rule)

examples = [3, 6, 9]

rules = make_rule_hypothesis_space()
intervals = make_interval_hypothesis_space(1, maxNumber)

n_rules = len(rules)
n_intervals = len(intervals)

# Prior weights: 50/50 split between rules and intervals, uniform within each
# Prior for each rule hypothesis: 0.5 / n_rules
# Prior for each interval hypothesis: 0.5 / n_intervals

# Precompute sets and log-likelihoods for all hypotheses
hypotheses = rules + intervals
n_hyp = len(hypotheses)

log_prior = []
for i in range(n_rules):
    log_prior.append(math.log(0.5) - math.log(n_rules))
for i in range(n_intervals):
    log_prior.append(math.log(0.5) - math.log(n_intervals))

# Precompute sets
sets = []
for h in hypotheses:
    s = get_set_from_hypothesis(h)
    sets.append(frozenset(s))

set_sizes = [len(s) for s in sets]

# Compute log-likelihood of examples for each hypothesis
log_likelihoods = []
for i, s in enumerate(sets):
    sz = set_sizes[i]
    if sz == 0:
        log_likelihoods.append(float('-inf'))
        continue
    ll = 0.0
    valid = True
    for ex in examples:
        if ex not in s:
            valid = False
            break
        ll += -math.log(sz)
    if not valid:
        log_likelihoods.append(float('-inf'))
    else:
        log_likelihoods.append(ll)

# Compute unnormalized log weights
log_weights = [log_prior[i] + log_likelihoods[i] for i in range(n_hyp)]

# Normalize
max_lw = max(log_weights)
weights = [math.exp(lw - max_lw) for lw in log_weights]
total = sum(weights)
weights = [w / total for w in weights]

# For each query, compute expected P(query in set)
ANSWER = []
for query in range(1, maxNumber + 1):
    prob = 0.0
    for i, s in enumerate(sets):
        if query in s:
            prob += weights[i]
    ANSWER.append(prob)

foods = ['bagel', 'cookie', 'doughnut']
actions = ['a', 'b', 'c']

# Vending machine: P(food | action)
vending = {
    'a': {'bagel': 0.8, 'cookie': 0.1, 'doughnut': 0.1},
    'b': {'bagel': 0.1, 'cookie': 0.8, 'doughnut': 0.1},
    'c': {'bagel': 0.1, 'cookie': 0.1, 'doughnut': 0.8},
}

def choose_action_prob_b(goal_food, deceive):
    # P(action='b') given goal and deceive
    weights = {}
    for act in actions:
        if deceive:
            # want outcome != goal_food
            weights[act] = 1.0 - vending[act][goal_food]
        else:
            # want outcome == goal_food
            weights[act] = vending[act][goal_food]
    total = sum(weights.values())
    return weights['b'] / total

# Enumerate over deceive x goalFood
# Prior: deceive=True with p=0.5, goalFood uniform over 3 foods
goal_weights = {'bagel': 0.0, 'cookie': 0.0, 'doughnut': 0.0}

for deceive in [False, True]:
    p_deceive = 0.5
    for goal_food in foods:
        p_goal = 1.0 / 3.0
        p_b = choose_action_prob_b(goal_food, deceive)
        # Observe 'b' twice independently
        p_obs = p_b * p_b
        joint = p_deceive * p_goal * p_obs
        goal_weights[goal_food] += joint

total = sum(goal_weights.values())
norm = {f: goal_weights[f] / total for f in foods}

sorted_foods = sorted(foods)
probs = [norm[f] for f in sorted_foods]

ANSWER = {"__kind": "distribution", "probs": probs, "support": sorted_foods}

import itertools

doors = [1, 2, 3]

# Enumerate all (aliceDoor, prizeDoor, montyDoor)
# Prior: uniform over alice, prize, monty
# montyAvoidAlice: monty picks uniformly from doors != alice (prob 1/2 each)
# Condition on: montyDoor != prizeDoor AND montyDoor != aliceDoor

def compute_posterior(switches):
    total_weight = 0.0
    win_weight = 0.0
    for alice in doors:
        for prize in doors:
            # monty picks from doors != alice, uniformly
            valid_monty_choices = [d for d in doors if d != alice]
            for monty in valid_monty_choices:
                # weight: 1/3 * 1/3 * 1/2
                w = (1.0/3) * (1.0/3) * (1.0/len(valid_monty_choices))
                # condition on monty != prize and monty != alice
                if monty == prize or monty == alice:
                    continue
                # determine alice's final door
                if switches:
                    remaining = [d for d in doors if d != alice and d != monty]
                    final_door = remaining[0]
                else:
                    final_door = alice
                wins = (final_door == prize)
                total_weight += w
                if wins:
                    win_weight += w
    p_win = win_weight / total_weight
    return p_win

p_win_stay = compute_posterior(False)
p_win_switch = compute_posterior(True)

ANSWER = {
    'stay': {
        '__kind': 'distribution',
        'probs': [1.0 - p_win_stay, p_win_stay],
        'support': [False, True]
    },
    'switch': {
        '__kind': 'distribution',
        'probs': [1.0 - p_win_switch, p_win_switch],
        'support': [False, True]
    }
}
